import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import './Visualization.css';

function Visualization() {
  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('age');
  const [selectedY, setSelectedY] = useState('bmi');
  const [chartData, setChartData] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    axios.get('http://localhost:8000/data/columns')
      .then(res => {
        setColumns(res.data.columns);
        // Auto-select first two columns
        if (res.data.columns.length >= 2) {
          setSelectedX(res.data.columns[0]);
          setSelectedY(res.data.columns[1]);
        }
      });
  }, []);

  useEffect(() => {
    if (selectedX && selectedY) {
      setLoading(true);
      axios.get('http://localhost:8000/data/sample', {
        params: { x: selectedX, y: selectedY }
      })
      .then(res => {
        const data = [
          [selectedX, selectedY],
          ...res.data.map(item => [item[selectedX], item[selectedY]])
        ];
        setChartData(data);
      })
      .finally(() => setLoading(false));
    }
  }, [selectedX, selectedY]);

  return (
    <div className="visualization-container">
      <h2>Data Visualization</h2>
      
      <div className="controls">
        <div className="control-group">
          <label>X-Axis:</label>
          <select 
            value={selectedX} 
            onChange={e => setSelectedX(e.target.value)}
            disabled={loading || columns.length === 0}
          >
            {columns.map(col => (
              <option key={`x-${col}`} value={col}>{col}</option>
            ))}
          </select>
        </div>

        <div className="control-group">
          <label>Y-Axis:</label>
          <select 
            value={selectedY} 
            onChange={e => setSelectedY(e.target.value)}
            disabled={loading || columns.length === 0}
          >
            {columns.map(col => (
              <option key={`y-${col}`} value={col}>{col}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <div className="loading">Loading chart data...</div>
      ) : chartData.length > 1 ? (
        <Chart
          chartType="ScatterChart"
          width="100%"
          height="400px"
          data={chartData}
          options={{
            title: `${selectedY} vs ${selectedX}`,
            hAxis: { title: selectedX },
            vAxis: { title: selectedY },
            legend: 'none'
          }}
        />
      ) : (
        <div className="no-data">
          {columns.length === 0 ? "Loading available columns..." : "Select parameters to visualize"}
        </div>
      )}
    </div>
  );
}

export default Visualization;
